@dataclass(frozen=True)
class EvidenceIndex:
    pairs: tuple[EvidencePair, ...]

    def matches(self, excerpt: str) -> tuple[EvidencePair, ...]:
        return tuple(
            pair
            for pair in self.pairs
            if any(excerpt in text for text in pair.text_blocks)
        )


