  cmd: "pixi run python - <<'PY'
import json
import re
from pathlib import Path

base = Path('src/detours/detour_ai_augment/data/sample_run')
rollout_path = base / '.codex/sessions/2026/08/04/rollout-2026-08-04T12-56-18-019fcdb4-5f96-7821-ad66-747c885cc4bd.jsonl'
final_path = base / 'ai-2026-08-04/aziz_sheikh_annotation.json'
records = [json.loads(line) for line in rollout_path.read_text().splitlines()]

HUNK = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')
def apply_diff(old: str, diff: str) -> str:
    old_lines = old.splitlines(keepends=True)
    diff_lines = diff.splitlines(keepends=True)
    result = []
    old_index = 0
    index = 0
    while index < len(diff_lines):
        match = HUNK.match(diff_lines[index])
        if not match:
            index += 1
            continue
        target = int(match.group(1)) - 1
        result.extend(old_lines[old_index:target])
        old_index = target
        index += 1
        while index < len(diff_lines) and not HUNK.match(diff_lines[index]):
            line = diff_lines[index]
            if line.startswith(' '):
                assert old_lines[old_index] == line[1:], (old_index, old_lines[old_index], line)
                result.append(line[1:])
                old_index += 1
            elif line.startswith('-'):
                assert old_lines[old_index] == line[1:], (old_index, old_lines[old_index], line)
                old_index += 1
            elif line.startswith('+'):
                result.append(line[1:])
            elif not line.startswith('\\'):
                raise AssertionError(('unsupported diff line', line))
            index += 1
    result.extend(old_lines[old_index:])
    return ''.join(result)

outputs = {}
web_calls = {}
for line_number, record in enumerate(records, 1):
    payload = record.get('payload')
    if not isinstance(payload, dict):
        continue
    if (
        record.get('type') == 'response_item'
        and payload.get('type') == 'custom_tool_call'
        and payload.get('name') == 'exec'
        and isinstance(payload.get('input'), str)
        and payload['input'].lstrip().startswith('const r = await tools.web__run(')
    ):
        web_calls[payload['call_id']] = (line_number, record)
    elif record.get('type') == 'response_item' and payload.get('type') == 'custom_tool_call_output':
        outputs[payload.get('call_id')] = (line_number, record)

web_pairs = []
for call_id, (call_line, call) in web_calls.items():
    if call_id not in outputs:
        continue
    output_line, output = outputs[call_id]
    output_value = output['payload']['output']
    blocks = tuple(block['text'] for block in output_value if block.get('type') == 'input_text')
    web_pairs.append((call_id, call_line, output_line, blocks))

file_content = None
pushes = []
for line_number, record in enumerate(records, 1):
    payload = record.get('payload')
    if isinstance(payload, dict) and payload.get('type') == 'patch_apply_end':
        change = payload.get('changes', {}).get('/home/ai/aziz_sheikh_annotation.json')
        if change:
            if 'content' in change:
                file_content = change['content']
            if 'unified_diff' in change:
                assert file_content is not None
                file_content = apply_diff(file_content, change['unified_diff'])
    if not isinstance(payload, dict) or payload.get('type') != 'custom_tool_call' or line_number < 232:
        continue
    command = payload.get('input')
    if not isinstance(command, str) or '/push' not in command:
        continue
    assert file_content is not None
    submitted = json.loads(file_content)
    transformed = 'with_entries(.value.web_search_excerpts |= [.[0]])' in command
    if transformed:
        submitted = {
            field: {**item, 'web_search_excerpts': item['web_search_excerpts'][:1]}
            for field, item in submitted.items()
        }
    pushes.append((line_number, record.get('timestamp'), transformed, submitted))

assert file_content == final_path.read_text(), 'reconstructed final payload differs from committed sample'
print('reconstruction_matches_final', True)
print('web_pairs', len(web_pairs))
for line_number, timestamp, transformed, submitted in pushes:
    matches = []
    missing = []
    for field, item in submitted.items():
        for excerpt in item['web_search_excerpts']:
            pair_ids = [
                call_id
                for call_id, _call_line, output_line, blocks in web_pairs
                if output_line <= line_number and any(excerpt in block for block in blocks)
            ]
            if pair_ids:
                matches.append((field, excerpt, pair_ids))
            else:
                missing.append((field, excerpt))
    print(json.dumps({
        'push_line': line_number,
        'timestamp': timestamp,
        'first_excerpt_only_transform': transformed,
        'excerpt_count': len(matches) + len(missing),
        'matched_in_completed_web_custom_output': len(matches),
        'missing': [{'field': field, 'excerpt': excerpt} for field, excerpt in missing],
    }, ensure_ascii=False))
PY",
