import json
from pathlib import Path

base = Path('src/detours/detour_ai_augment/data/sample_run')
rollout_path = base / '.codex/sessions/2026/08/04/rollout-2026-08-04T12-56-18-019fcdb4-5f96-7821-ad66-747c885cc4bd.jsonl'
annotation = json.loads((base / 'ai-2026-08-04/aziz_sheikh_annotation.json').read_text())
records = [json.loads(line) for line in rollout_path.read_text().splitlines()]
outputs = {}
for line_number, record in enumerate(records, 1):
    payload = record.get('payload')
    if isinstance(payload, dict) and record.get('type') == 'response_item' and payload.get('type') == 'custom_tool_call_output':
        outputs[payload.get('call_id')] = (line_number, record)
pairs = []
for call_line, call in enumerate(records, 1):
    payload = call.get('payload')
    if not (
        isinstance(payload, dict)
        and call.get('type') == 'response_item'
        and payload.get('type') == 'custom_tool_call'
        and payload.get('name') == 'exec'
        and isinstance(payload.get('input'), str)
        and payload['input'].lstrip().startswith('const r = await tools.web__run(')
    ):
        continue
    call_id = payload['call_id']
    output_line, output = outputs[call_id]
    blocks = tuple(block['text'] for block in output['payload']['output'] if block.get('type') == 'input_text')
    events = []
    for event_line in range(call_line + 1, output_line):
        event = records[event_line - 1]
        event_payload = event.get('payload')
        if isinstance(event_payload, dict) and event.get('type') == 'event_msg' and event_payload.get('type') == 'web_search_end':
            events.append((event_line, event))
    actions = [action for action in ('search_query', 'open', 'click') if f'{action}:' in payload['input']]
    pairs.append((call_id, call_line, output_line, actions, tuple(events), blocks))

for field, item in annotation.items():
    for excerpt in item['web_search_excerpts']:
        matches = []
        for call_id, call_line, output_line, actions, events, blocks in pairs:
            if not any(excerpt in block for block in blocks):
                continue
            event_contains = any(
                excerpt in text
                for _event_line, event in events
                for result in event['payload'].get('results', [])
                for text in result.values()
                if isinstance(text, str)
            )
            matches.append({
                'call_id': call_id,
                'call_line': call_line,
                'output_line': output_line,
                'actions': actions,
                'event_lines': [line for line, _event in events],
                'event_contains_excerpt': event_contains,
            })
        print(json.dumps({
            'field': field,
            'excerpt': excerpt,
            'matching_pair_count': len(matches),
            'matching_pairs': matches,
        }, ensure_ascii=False))
