import re
from datetime import datetime
from pathlib import Path
from zipfile import ZipFile

import pandas as pd
from lxml import etree

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
W15 = "http://schemas.microsoft.com/office/word/2012/wordml"
NS = {"w": W, "w15": W15}


def _fmt_flags(r):
    rPr = r.find("w:rPr", namespaces=NS)
    if rPr is None:
        return False, False, False, False

    bold = rPr.find("w:b", namespaces=NS) is not None
    italic = rPr.find("w:i", namespaces=NS) is not None

    sub = sup = False
    va = rPr.find("w:vertAlign", namespaces=NS)
    if va is not None:
        val = va.get(f"{{{W}}}val")  # w:val
        sub = (val == "subscript")
        sup = (val == "superscript")

    return bold, italic, sub, sup


def _wrap(txt, bold, italic, sub, sup):
    if txt == "":
        return txt
    if bold:
        txt = f"**{txt}**"
    if italic:
        txt = f"_{txt}_"
    if sub:
        txt = f"~{txt}~"
    if sup:
        txt = f"^{txt}^"
    return txt


def _run_to_text(r):
    bold, italic, sub, sup = _fmt_flags(r)
    out = []
    for child in r:
        tag = etree.QName(child).localname
        if tag == "t":
            out.append(_wrap(child.text or "", bold, italic, sub, sup))
        elif tag == "tab":
            out.append("\t")
        elif tag in ("br", "cr"):
            out.append("\n")
        # ignore other run children (drawing, fldChar, etc.) but they don't contain visible text
    return "".join(out)


def _run_to_text_plain(r):
    out = []
    for child in r:
        tag = etree.QName(child).localname
        if tag == "t":
            out.append(child.text or "")
        elif tag == "tab":
            out.append("\t")
        elif tag in ("br", "cr"):
            out.append("\n")
    return "".join(out)


